import json
import sys
from pathlib import Path
sys.path.insert(0, '/workspace')
from robot import Client, ClientError

try:
    reply = Client().history(after=0, limit=35)
except ClientError as exc:
    print(json.dumps(exc.document()))
    raise SystemExit(3)
Path('/workspace/notes/startup-history-1-35.json').write_text(json.dumps(reply), encoding='utf-8')
print(json.dumps({k: v for k, v in reply.items() if k "'!= '"'events'}))
for event in reply.get('events', []):
    item = {k: event[k] for k in ('event_id', 'type', 'sim_time_s', 'owner', 'authority_epoch', 'source') if k in event}
    payload = event.get('payload', {})
    if event.get('type') == 'observation':
        item['payload'] = {k: payload.get(k) for k in ('sequence', 'capture_sim_time_s', 'detections', 'station', 'gripper', 'inspection', 'last_feedback')}
    else:
        item['payload'] = payload
    print(json.dumps(item))
PY
